".material-card {
  background-color: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: var(--border-radius-lg);
  padding: 20px;
  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.05);
  cursor: pointer;
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

.material-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 20px -8px rgba(59, 130, 246, 0.25), 0 4px 6px -2px rgba(139, 92, 246, 0.15);
  border-color: #3b82f6;
}

.card-badge-level {
  font-size: 9px;
  font-weight: 800;
  padding: 4px 8px;
  border-radius: 12px;
  background-color: #f1f5f9;
  color: #475569;
  border: 1px solid #e2e8f0;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.card-badge-reward {
  font-size: 9px;
  font-weight: 800;
  padding: 4px 8px;
  border-radius: 12px;
  background-color: #fffbeb;
  color: #d97706;
  border: 1px solid #fde68a;
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.card-badge-reward.advanced {
  background-color: #faf5ff;
  color: #7c3aed;
  border: 1px solid #e9d5ff;
}

.material-card-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  margin-top: 4px;
}

.material-card-title-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.mat-icon-circle {
